import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import { useState, useEffect } from "react";
import { API } from "../api/api";

export default function Home() {
  const nav = useNavigate();

  const [polls, setPolls] = useState([]);
  const [surveys, setSurveys] = useState([]);

  const [category, setCategory] = useState("all");

  const [loadingPolls, setLoadingPolls] = useState(false);
  const [loadingSurveys, setLoadingSurveys] = useState(false);

  // ✅ AUTO LOAD DATA
  useEffect(() => {
    fetchPolls();
    fetchSurveys();
  }, []);

  const fetchPolls = async () => {
    try {
      setLoadingPolls(true);
      const res = await API.get("/polls");
      setPolls(res.data || []);
    } catch (err) {
      console.log("Poll fetch error", err);
      setPolls([]);
    } finally {
      setLoadingPolls(false);
    }
  };

  const fetchSurveys = async () => {
    try {
      setLoadingSurveys(true);
      const res = await API.get("/surveys"); // ⚠️ make sure backend supports this
      setSurveys(res.data || []);
    } catch (err) {
      console.log("Survey fetch error", err);
      setSurveys([]);
    } finally {
      setLoadingSurveys(false);
    }
  };

  return (
    <>
      <Navbar />

      <style>{`
        .home-container{
          min-height:100vh;
          padding:40px;
          color:white;
          background: radial-gradient(circle at top,#1e3a8a,#0b1220 60%);
        }

        .hero{
          text-align:center;
          margin-bottom:30px;
        }

        .hero h1{
          font-size:38px;
          font-weight:800;
        }

        .category-bar{
          display:flex;
          justify-content:center;
          gap:10px;
          margin-bottom:30px;
        }

        .category-bar button{
          padding:8px 16px;
          border:none;
          border-radius:20px;
          background:#1f2937;
          color:white;
          cursor:pointer;
        }

        .active-cat{
          background:#3b82f6 !important;
        }

        .container{
          display:flex;
          justify-content:center;
          gap:40px;
          flex-wrap:wrap;
        }

        .card{
          width:400px;
          border-radius:18px;
          background:#111827;
          padding:20px;
        }

        .title{
          font-size:20px;
          font-weight:700;
          margin-bottom:10px;
        }

        .plus-btn{
          width:50px;
          height:50px;
          border-radius:50%;
          border:none;
          font-size:22px;
          cursor:pointer;
          color:white;
          margin-top:10px;
        }

        .poll-item, .survey-item{
          padding:10px;
          margin:8px 0;
          background:#1f2937;
          border-radius:10px;
          cursor:pointer;
        }

        .poll-item:hover, .survey-item:hover{
          background:#374151;
        }
      `}</style>

      <div className="home-container">

        <div className="hero">
          <h1>Survey Hub 🚀</h1>
        </div>

        {/* CATEGORY */}
        <div className="category-bar">
          {["all", "student", "teacher", "general"].map(cat => (
            <button
              key={cat}
              onClick={() => setCategory(cat)}
              className={category === cat ? "active-cat" : ""}
            >
              {cat.toUpperCase()}
            </button>
          ))}
        </div>

        <div className="container">

          {/* POLLS */}
          
<div className="card">
  <div className="bar poll-bar"></div>

  <div className="card-header">
    <div>📊</div>
    <div className="title">Polls</div>
  </div>

  <div className="card-body">

    {!showPolls ? (
      <>
        <div
          className="start-text"
          onClick={() => {
            setShowPolls(true);
            fetchPolls();
          }}
        >
          VIEW POLLS
        </div>

        <button
          className="plus-btn"
          onClick={() => nav("/create-poll")}
        >
          +
        </button>
      </>
    ) : (
      <>
        <h3>All Polls</h3>

        {polls.length === 0 ? (
          <p>No polls found</p>
        ) : (
          polls.map(p => (
            <div
              key={p._id}
              className="poll-item"
              onClick={() => nav(`/poll/${p._id}`)}
            >
              {p.question}
            </div>
          ))
        )}

        <button className="back-btn" onClick={() => setShowPolls(false)}>
          ← Back
        </button>
      </>
    )}

  </div>
</div>

          {/* SURVEYS */}
          <div className="card">
            <div className="title">📝 Surveys</div>

            <button
              className="plus-btn"
              style={{ background: "#3b82f6" }}
              onClick={() => nav("/create-survey")}
            >
              +
            </button>

            {loadingSurveys ? (
              <p>Loading surveys...</p>
            ) : surveys.filter(s => category === "all" || s.category === category).length === 0 ? (
              <p>No surveys found</p>
            ) : (
              surveys
                .filter(s => category === "all" || s.category === category)
                .map(s => (
                  <div
                    key={s._id}
                    className="survey-item"
                    onClick={() => nav(`/survey/${s._id}`)}
                  >
                    {s.title}
                  </div>
                ))
            )}
          </div>

        </div>
      </div>
    </>
  );
}
